```tsx
import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Sample = {
  RORDEN: string;
  RCOMIS: string;
  RMOVIM: string;
  RMENS: string;
};

const SAMPLES: Record<string, Sample> = {
  ok: {
    RORDEN: '0001234',
    RCOMIS: '1,250.00',
    RMOVIM: '4587231',
    RMENS: 'PAGO APLICADO CORRECTAMENTE',
  },
  rechazado: {
    RORDEN: '0001235',
    RCOMIS: '0.00',
    RMOVIM: '0',
    RMENS: 'PAGO RECHAZADO',
  },
  vacio: {
    RORDEN: '',
    RCOMIS: '',
    RMOVIM: '',
    RMENS: '',
  },
};

export default function PagoResultado({ navigate }: { navigate: (to: string) => void }) {
  // Estado de ejemplo solo para el prototipo: permite revisar los estados de la pantalla.
  const [estado, setEstado] = useState<string>('ok');
  const data = SAMPLES[estado];
  const noop = () => {};

  const nuevoPago = () => navigate('SCR-PAGOORD');
  const menu = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Resultado del pago"
      code="PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: nuevoPago, primary: true },
            { key: 'PF3', label: 'Menú', onPress: menu },
          ]}
        />
      }
    >
      <Stack>
        {estado === 'ok' && (
          <Alert tone="success">El pago se procesó y el resultado se muestra a continuación.</Alert>
        )}
        {estado === 'rechazado' && (
          <Alert tone="error">El pago no pudo aplicarse. Revise el resultado informado.</Alert>
        )}
        {estado === 'vacio' && (
          <Alert tone="info">No hay un resultado de pago para mostrar. Inicie un nuevo pago.</Alert>
        )}

        <Card title="Resultado del pago">
          <Grid columns={2}>
            <div data-field="RORDEN">
              <TextField
                label="Orden"
                hint="Número de orden, 7 dígitos"
                maxLength={7}
                numeric
                readOnly
                value={data.RORDEN}
                onChange={noop}
              />
            </div>

            <div data-field="RCOMIS">
              <TextField
                label="Comisión"
                hint="Formato ZZZ,ZZ9.99"
                maxLength={10}
                numeric
                readOnly
                value={data.RCOMIS}
                onChange={noop}
              />
            </div>

            <div data-field="RMOVIM">
              <TextField
                label="Movimiento"
                hint="Número de movimiento, hasta 10 dígitos"
                maxLength={10}
                numeric
                readOnly
                value={data.RMOVIM}
                onChange={noop}
              />
            </div>

            <div data-field="RMENS">
              <TextField
                label="Resultado"
                hint="Mensaje del resultado, hasta 40 caracteres"
                maxLength={40}
                readOnly
                value={data.RMENS}
                onChange={noop}
              />
            </div>
          </Grid>

          <Row>
            <Button variant="primary" shortcut="ENTER" onClick={nuevoPago}>
              Nuevo pago
            </Button>
            <Button variant="secondary" shortcut="PF3" onClick={menu}>
              Menú
            </Button>
          </Row>
        </Card>

        <Card title="Vista de ejemplo (solo prototipo)">
          <Row>
            <Badge>Prototipo</Badge>
            <SelectField
              label="Estado a visualizar"
              options={[
                { value: 'ok', label: 'Pago aplicado' },
                { value: 'rechazado', label: 'Pago rechazado' },
                { value: 'vacio', label: 'Sin resultado' },
              ]}
              value={estado}
              onChange={(v: string) => setEstado(v)}
            />
          </Row>
        </Card>
      </Stack>
    </Screen>
  );
}
